      form.append('publicTitle',$('#publicTitle').value.trim()||$('#name').value.trim());
      form.append('adLabel',$('#adLabel').value.trim()||'PUBLICIDADE · SHOPLAB ADS');
      form.append('showHeader',$('#showHeader').checked?'1':'0');
      form.append('dismissible',$('#dismissible').checked?'1':'0');
      form.append('dismissMinutes',$('#dismissMinutes').value||'30');
      form.append('ctaText',$('#ctaText').value.trim()||'Saiba mais');
      form.append('ctaColor',$('#ctaColor').value||'#075fce');form.append('oldPriceText',$('#oldPriceText').value.trim());form.append('oldPriceColor',$('#oldPriceColor').value||'#71807c');form.append('currentPriceText',$('#currentPriceText').value.trim());form.append('currentPriceColor',$('#currentPriceColor').value||'#087c70');
      if(file)form.append('file',file);
      await api(editId?`/api/v1/admin/shoplab-ads/${encodeURIComponent(editId)}`:'/api/v1/admin/shoplab-ads',{method:editId?'PUT':'POST',body:form});
      ads=await loadAds();
