async function loadAds(){const rows=await api('/api/v1/admin/shoplab-ads');return rows.map(row=>({id:row.id,name:row.name,status:row.status==='active'?'published':row.status==='paused'?'paused':'draft',mediaType:row.mediaType==='video'?'Video':'Imagem',mediaUrl:row.storageKey?`${C.API_BASE_URL}/media/${encodeURIComponent(row.storageKey)}`:'',linkUrl:row.linkUrl||'',priority:Number(row.priority)||1,publicTitle:row.publicTitle||row.name,adLabel:row.adLabel||'PUBLICIDADE · SHOPLAB ADS',showHeader:Number(row.showHeader)!==0,dismissible:Number(row.dismissible)!==0,dismissMinutes:Number(row.dismissMinutes)||30,ctaText:row.ctaText||'Saiba mais',ctaColor:row.ctaColor||'#075fce',productSlug:row.productSlug||'',oldPriceText:row.oldPriceText||(row.linkedOldPrice!=null?'R$ '+(Number(row.linkedOldPrice)/100).toFixed(2).replace('.',','):''),oldPriceColor:row.oldPriceColor||'#71807c',currentPriceText:row.currentPriceText||(row.linkedCurrentPrice!=null?'R$ '+(Number(row.linkedCurrentPrice)/100).toFixed(2).replace('.',','):''),currentPriceColor:row.currentPriceColor||'#087c70',targetKeywords:row.targetKeywords||'',distributionMode:row.distributionMode==='weighted'?'weighted':'manual',distributionWeight:Math.max(1,Math.min(100,Number(row.distributionWeight)||25)),featured:Boolean(Number(row.featured)),searchBoost:Math.max(1,Math.min(10,Number(row.searchBoost)||3)),maxPerPage:Math.max(1,Math.min(4,Number(row.maxPerPage)||1)),targetPages:row.targetPages||'home,products,category,product',startsAt:row.startsAt||'',endsAt:row.endsAt||'',noEndDate:Number(row.noEndDate)!==0,categorySlugs:row.categorySlugs||'',relatedProductSlugs:row.relatedProductSlugs||'',derivedStatus:row.derivedStatus||row.status}))}

async function loadAdProductOptions(){const products=await api('/api/v1/products?limit=50').catch(()=>[]);const list=$('#shoplab-product-options');list.innerHTML=products.map(product=>'<option value="'+esc(product.slug)+'" label="'+esc(product.name)+'"></option>').join('')}async function init(sessionOverride){adminSession=sessionOverride||await api('/api/v1/admin/auth/session');shell();document.querySelector('.admin-main')?.classList.add('ads-editor');const heading=document.querySelector('.admin-heading');if(heading&&!heading.querySelector('.muted'))heading.insertAdjacentHTML("beforeend","<p class='muted'>Gerencie campanhas patrocinadas, distribuição e desempenho.</p>");setupAnalyticsUi();await loadAdsSettings();if(!canAd('shoplab_ads.analytics'))$('[data-ads-view=analytics]')?.remove();await loadAdProductOptions();ads=await loadAds();const assignments=await api('/api/v1/admin/shoplab-ad-assignments');placements={desktop:{},mobile:{}};for(const item of assignments)if(!['top','menu'].includes(item.positionKey)){const map=placementMap(item.device,item.pageKind),ids=Array.isArray(map[item.positionKey])?map[item.positionKey]:[];if(!ids.includes(item.adId))map[item.positionKey]=[...ids,item.adId]}renderLibrary();renderPositions();bind()}
window.ShoplabAdsAdmin={run:(_target,session)=>init(session)};
